"""Local operator control, no model access; exact inputs/results stay in server journal."""
import json,sys,urllib.request
from pathlib import Path
root=Path('/tmp/mvc-acceptance-20261030')
mode=sys.argv[1];body=json.loads(sys.argv[2]) if len(sys.argv)>2 else {}
url='http://127.0.0.1:8004/evaluation/'+mode
headers={'Content-Type':'application/json','x-control':json.loads((root/'control.json').read_text())['token']}
request=urllib.request.Request(url,data=None if mode=='status' else json.dumps(body).encode(),headers=headers)
with urllib.request.urlopen(request,timeout=310) as response: result=json.load(response)
if 'assessment' in result:
 a=result.pop('assessment');result.pop('facts',None)
 if a:result['result']={'disposition':a['disposition'],'recommendation':a['recommendation']['summary'],
     'open_decisions':[q['text'] for q in a['open_questions']]}
if 'response' in result:
 r=result.pop('response')
 if r:result.update(question=r['question'],owner_view=r['owner_view'],disposition=r['developer_view']['disposition'])
print(json.dumps(result,ensure_ascii=False,indent=2))
